import {
    type Diagnostic,
    FileSystem,
    type File,
    ts,
    path as pathModule,
    Database,
    type ProjectFile as IProjectFile,
    type Shape,
    Formatter,
    type Compiler,
    isFluentNode,
    getUnsupportedKindName,
    hasDirective,
    type Record,
} from '@servicenow/sdk-build-core'
import { getOutput, writeFileWithParentDirs } from './util'
import type { Project } from './project'

export class ProjectFile implements IProjectFile {
    constructor(
        private readonly file: ts.SourceFile | File,
        private readonly project: Project,
        private readOnly: boolean = false
    ) {}

    getPath(): string {
        return pathModule.normalize(this.file instanceof ts.SourceFile ? this.file.getFilePath() : this.file.path)
    }

    getName(): string {
        return pathModule.basename(this.getPath())
    }

    getContent(): string {
        return this.file instanceof ts.SourceFile ? this.file.getFullText() : this.file.content
    }

    setContent(content: string): void {
        if (this.file instanceof ts.SourceFile) {
            this.file.replaceText([this.file.getPos(), this.file.getEnd()], content)
        } else {
            this.file.content = content
        }

        this.reload(false)
    }

    setReadOnly(readOnly: boolean): void {
        this.readOnly = readOnly
    }

    async getDiagnostics(): Promise<Diagnostic[]> {
        await this.getRecords(false)
        return this.project.getDiagnosticsService().getAll(this.getPath())
    }

    async getShapes(throwOnError = true): Promise<Shape[]> {
        const shapes: Shape[] = []
        const { diagnostics, compiler, transform, logger } = this.project.getContext()

        if (this.isKeysRegistry()) {
            return shapes
        }

        if (this.file instanceof ts.SourceFile) {
            diagnostics.clear(this.getPath())
            compiler.getDiagnosticsForFluentFile(this.file).forEach((d) => diagnostics.add(d))

            const filePath = this.file.getFilePath()
            await compiler.visitSupportedNodes(
                this.file,
                async (node) => {
                    try {
                        const result = await transform.toShape(node)
                        if (result.success && filePath === result.value.getOriginalFilePath()) {
                            shapes.push(result.value)
                        }
                    } catch (e) {
                        logger.error('Shape creation failed:', e)
                    }
                },
                (node) => {
                    if (isFluentNode(node)) {
                        diagnostics.error(
                            node,
                            `Syntax kind "${getUnsupportedKindName(node)}" is not allowed in Fluent files.`
                        )
                    }
                }
            )
        }

        if (throwOnError) {
            const errors = diagnostics.getErrors(this.getPath())
            errors.forEach((e) => logger.error(e.getFormattedText()))
            if (errors.length > 0) {
                throw new Error(
                    `Found ${errors.length} diagnostic error(s) while getting shapes from file: ${this.getPath()}`
                )
            }
        }

        return shapes
    }

    async getRecords(throwOnError = true): Promise<Database> {
        return new Database(await this.getRecordsNoDedupe(throwOnError))
    }

    async getRecordsNoDedupe(throwOnError = true, sysIds?: Set<string>): Promise<Record[]> {
        const records: Record[] = []
        const { diagnostics, compiler, transform, keys, logger, inspect } = this.project.getContext()

        if (this.getPath() === keys.getFilePath()) {
            return records
        }

        if (this.file instanceof ts.SourceFile) {
            diagnostics.clear(this.getPath())
            compiler.getDiagnosticsForFluentFile(this.file).forEach((d) => diagnostics.add(d))

            const filePath = this.file.getFilePath()
            await compiler.visitSupportedNodes(
                this.file,
                async (node) => {
                    const plugins = this.project.getPlugins()
                    const context = this.project.getContext()
                    const entryPoint = ts.Node.isSourceFile(node) ? node.getFilePath() : node

                    if (await plugins.isEntryPoint(entryPoint, context)) {
                        try {
                            const result = await transform.toRecord(node)
                            if (result.success && filePath === result.value.getOriginalFilePath()) {
                                const flatResult = result.value.flat()
                                if (
                                    !sysIds ||
                                    (sysIds && flatResult.find((value) => sysIds?.has(value.getId().getValue())))
                                ) {
                                    records.push(...flatResult)
                                }
                            }
                        } catch (e) {
                            logger.error('Record creation failed:', e)
                        }
                    }
                },
                (node) => {
                    if (isFluentNode(node)) {
                        diagnostics.error(
                            node,
                            `Node kind "${getUnsupportedKindName(node)}" is not allowed in Fluent files.`
                        )
                    }
                }
            )
        } else {
            const filePath = this.file.path
            try {
                const result = await transform.toRecord(this.file)
                if (result.success) {
                    if (filePath === result.value.getOriginalFilePath() || this.isUpdateSetXml()) {
                        const flatResult = result.value.flat()
                        if (!sysIds || (sysIds && flatResult.find((value) => sysIds?.has(value.getId().getValue())))) {
                            records.push(...flatResult)
                        }
                    }
                }
            } catch (e) {
                logger.error('Record creation failed:', e)
            }
        }

        records.forEach((r) => inspect(r))

        if (throwOnError) {
            const errors = diagnostics.getErrors(this.getPath())
            errors.forEach((e) => logger.error(e.getFormattedText()))
            if (errors.length > 0) {
                throw new Error(
                    `Found ${errors.length} diagnostic error(s) while getting shapes from file: ${this.getPath()}`
                )
            }
        }

        return records
    }

    async getOutput(throwOnError = true): Promise<File[]> {
        return getOutput(await this.getRecords(throwOnError), this.project.getContext())
    }

    isUpdateSetXml() {
        if (this.file instanceof ts.SourceFile) {
            return false
        }
        if (this.file.path.match('sys_remote_update_set') || this.file.path.match('sys_update_set')) {
            return this.file.path.endsWith('.xml')
        }
        return false
    }

    isInMetadataDir(): boolean {
        return this.project.isInMetadataDir(this.getPath())
    }

    isInServerModulesDir(): boolean {
        return this.project.isInServerDir(this.getPath())
    }

    isInUiHtmlContentDir(): boolean {
        return this.project.isInUiHtmlContentDir(this.getPath())
    }

    isKeysRegistry(): boolean {
        return this.getPath() === this.project.getKeys().getFilePath()
    }

    reload(refreshFromFileSystem = true): void {
        if (this.file instanceof ts.SourceFile) {
            this.project.getDiagnosticsService().clear(this.getPath())
            this.project.getCompiler().removeTableInterfaceFromGlobalDeclaration(this.file)
        }

        this.project
            .getPlugins()
            .toArray()
            .forEach((plugin) => {
                plugin.flushCache()
            })

        if (refreshFromFileSystem) {
            if (this.file instanceof ts.SourceFile) {
                this.file.refreshFromFileSystemSync()
            } else if (FileSystem.existsSync(this.project.getFileSystem(), this.file.path)) {
                this.file.content = this.project.getFileSystem().readFileSync(this.file.path, { encoding: 'utf-8' })
            }
        }

        if (this.isKeysRegistry()) {
            this.project.getKeys().reload()
        }
    }

    fix(): void {
        if (!(this.file instanceof ts.SourceFile)) {
            return
        }

        this.file.fixMissingImports()

        //uses the exact same APIs used inside `fixUnusedIdentifiers` API.
        //https://github.com/dsherret/ts-morph/blob/886ad69eca9566c38a23a7dbf6047e89ea8b0d3b/packages/ts-morph/src/compiler/ast/module/SourceFile.ts#L894
        deleteUnusedCode(this.file, this.project)

        //Handle https://github.com/dsherret/ts-morph/issues/961
        const fixedText = fixAdditionalTrailingCommas(this.getContent())
        this.setContent(fixedText)
    }

    // TODO: Why constrain to just ts.SourceFile?
    async format(formatter: Formatter = new Formatter(this.project.getFileSystem())): Promise<void> {
        if (this.file instanceof ts.SourceFile) {
            this.setContent(await formatter.format(this.getContent(), this.getPath()))
        }
    }

    save(): void {
        if (this.file instanceof ts.SourceFile) {
            this.file.saveSync()
        } else if (!this.readOnly) {
            writeFileWithParentDirs(this.project.getFileSystem(), this.file)
        }
    }

    remove(): void {
        if (this.file instanceof ts.SourceFile) {
            this.project.getDiagnosticsService().clear(this.getPath())
            const compiler = this.project.getCompiler()
            compiler.removeTableInterfaceFromGlobalDeclaration(this.getPath())
            compiler.removeSourceFile(this.file)
        }
    }

    unwrap(): ts.SourceFile | File {
        return this.file
    }

    addStatement(code?: string): ts.Statement {
        if (!(this.file instanceof ts.SourceFile)) {
            throw new Error(`Cannot add statement to non-TypeScript file: ${this.getPath()}`)
        }

        // TODO: Insert newlines between statements if we're adding to an existing file
        const [statement, otherStatement] = this.file.addStatements(code ?? 'undefined')
        if (!statement) {
            throw new Error('Expected statement to be generated')
        }

        if (otherStatement) {
            throw new Error(
                `Expected one statement to be generated, but found multiple. It's likely that a syntax error was inserted.\nProvided statement:\n${code}`
            )
        }

        return statement
    }
}

function fixAdditionalTrailingCommas(fileText: string): string {
    return fileText.replace(/,{2,}$/gm, ',')
}

const unusedChangesIterator = (
    file: ts.SourceFile,
    compiler: Compiler,
    callback: (change: ts.FileTextChanges) => void
) => {
    const unusedFixes = compiler.getLanguageService().getCombinedCodeFix(file, 'unusedIdentifier_delete')
    unusedFixes.getChanges().forEach((change) => {
        callback(change)
    })
}

/**
 * Uses language service code fixes to get unused identifiers fix and tries to fix call expressions assigned to unused identifiers.
 * Ex:
 *  before: const x = Entity({})
 *  after: Entity({})
 * @param file TypeScript file
 * @param compiler TypeScript compiler
 */
function fixUnusedCode(file: ts.SourceFile, compiler: Compiler) {
    if (hasDirective(file, '@fluent-disable-sync-for-file')) {
        return
    }

    unusedChangesIterator(file, compiler, (change) => {
        // pre-compute nodes to avoid getting incorrect nodes when the file is modified (node.replaceWithText below)
        const nodes = change.getTextChanges().map((textChange) => {
            return file.getDescendantAtPos(textChange.getSpan().getStart())
        })
        nodes.forEach((node) => {
            // if node is a comment node, the whole comment and sibling variable statement will be be removed
            // to avoid that we get the variable statement node
            if (
                node?.isKind(ts.SyntaxKind.SingleLineCommentTrivia) ||
                node?.isKind(ts.SyntaxKind.MultiLineCommentTrivia)
            ) {
                node = node?.getNextSiblingIfKind(ts.SyntaxKind.VariableStatement)
            } else {
                node = node?.getFirstAncestorByKind(ts.SyntaxKind.VariableStatement)
            }
            const variableStatement = node?.asKind(ts.SyntaxKind.VariableStatement)
            const callExp = variableStatement?.getDeclarations()[0]?.getInitializerIfKind(ts.SyntaxKind.CallExpression)
            if (callExp && node && !variableStatement?.isExported()) {
                node.replaceWithText(callExp.getText())
            }
        })
    })
}

function deleteUnusedCode(file: ts.SourceFile, project: Project) {
    fixUnusedCode(file, project.getCompiler())
    const unusedCodeArr: string[] = []
    unusedChangesIterator(file, project.getCompiler(), (change) => {
        change.getTextChanges().forEach((textChange) => {
            const textSpan = textChange.getSpan()
            unusedCodeArr.push(file.getFullText().substring(textSpan.getStart(), textSpan.getEnd()))
        })
        change.applyChanges()
    })
    if (unusedCodeArr.length > 0) {
        //logs all the code being removed during debug mode
        project
            .getLogger()
            .debug(
                [
                    `Removing the following unused code from ${file.getFilePath().replace(project.getRootDir(), '')}:`,
                    ...unusedCodeArr.map((unusedCode, idx) => `${idx + 1}:${unusedCode.trim()}`),
                ].join('\n\n')
            )
    }
    project.getCompiler().getLanguageService().getCombinedCodeFix(file, 'unusedIdentifier_deleteImports').applyChanges()
}
